{
  "root_cause": "The modal's _enforceFocus method only prevents focus from leaving the modal by forcing it back to the modal element, but does not handle Tab/Shift+Tab cycling among the modal's internal focusable elements. When Shift+Tab is pressed from the first focusable element (#confirm-close), the browser moves focus to the previous element in the document (outside the modal), triggering _enforceFocus which returns focus to the modal container instead of the last focusable element (#confirm-delete).",
  "repair_strategy": "Add a keydown handler on the modal element that traps Tab and Shift+Tab keys, cycling focus between the first and last focusable children of the modal. Install this handler when the modal is shown and remove it when hidden.",
  "edits": [
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "  _enforceFocus() {
    EventHandler.off(document, EVENT_FOCUSIN) // guard against infinite focus loop
    EventHandler.on(document, EVENT_FOCUSIN, event => {
      if (document !== event.target &&
          this._element !== event.target &&
          !this._element.contains(event.target)) {
        this._element.focus()
      }
    })
  }",
      "after": "  _enforceFocus() {
    EventHandler.off(document, EVENT_FOCUSIN) // guard against infinite focus loop
    EventHandler.on(document, EVENT_FOCUSIN, event => {
      if (document !== event.target &&
          this._element !== event.target &&
          !this._element.contains(event.target)) {
        this._element.focus()
      }
    })
  }

  _setFocusTrap() {
    const focusableSelector = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    const focusableElements = this._element.querySelectorAll(focusableSelector)
    if (focusableElements.length === 0) return

    const firstElement = focusableElements[0]
    const lastElement = focusableElements[focusableElements.length - 1]

    this._focusTrapHandler = (event) => {
      if (event.key !== 'Tab') return

      const activeElement = document.activeElement
      if (!this._element.contains(activeElement) && activeElement !== this._element) return

      if (event.shiftKey) {
        if (activeElement === firstElement || activeElement === this._element) {
          event.preventDefault()
          lastElement.focus()
        }
      } else {
        if (activeElement === lastElement) {
          event.preventDefault()
          firstElement.focus()
        }
      }
    }

    this._element.addEventListener('keydown', this._focusTrapHandler)
  }"
    },
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "  _showElement(relatedTarget) {
    const isAnimated = this._isAnimated()
    const modalBody = SelectorEngine.findOne(SELECTOR_MODAL_BODY, this._dialog)

    if (!this._element.parentNode || this._element.parentNode.nodeType !== Node.ELEMENT_NODE) {
      // Don't move modal's DOM position
      document.body.appendChild(this._element)
    }

    this._element.style.display = 'block'
    this._element.removeAttribute('aria-hidden')
    this._element.setAttribute('aria-modal', true)
    this._element.setAttribute('role', 'dialog')
    this._element.scrollTop = 0

    if (modalBody) {
      modalBody.scrollTop = 0
    }

    if (isAnimated) {
      reflow(this._element)
    }

    this._element.classList.add(CLASS_NAME_SHOW)

    if (this._config.focus) {
      this._enforceFocus()
    }

    const transitionComplete = () => {
      if (this._config.focus) {
        this._element.focus()
      }

      this._isTransitioning = false
      EventHandler.trigger(this._element, EVENT_SHOWN, {
        relatedTarget
      })
    }

    this._queueCallback(transitionComplete, this._dialog, isAnimated)
  }",
      "after": "  _showElement(relatedTarget) {
    const isAnimated = this._isAnimated()
    const modalBody = SelectorEngine.findOne(SELECTOR_MODAL_BODY, this._dialog)

    if (!this._element.parentNode || this._element.parentNode.nodeType !== Node.ELEMENT_NODE) {
      // Don't move modal's DOM position
      document.body.appendChild(this._element)
    }

    this._element.style.display = 'block'
    this._element.removeAttribute('aria-hidden')
    this._element.setAttribute('aria-modal', true)
    this._element.setAttribute('role', 'dialog')
    this._element.scrollTop = 0

    if (modalBody) {
      modalBody.scrollTop = 0
    }

    if (isAnimated) {
      reflow(this._element)
    }

    this._element.classList.add(CLASS_NAME_SHOW)

    if (this._config.focus) {
      this._enforceFocus()
      this._setFocusTrap()
    }

    const transitionComplete = () => {
      if (this._config.focus) {
        this._element.focus()
      }

      this._isTransitioning = false
      EventHandler.trigger(this._element, EVENT_SHOWN, {
        relatedTarget
      })
    }

    this._queueCallback(transitionComplete, this._dialog, isAnimated)
  }"
    },
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "  dispose() {
    [window, this._dialog]
      .forEach(htmlElement => EventHandler.off(htmlElement, EVENT_KEY))

    this._backdrop.dispose()
    super.dispose()

    /**
     * `document` has 2 events `EVENT_FOCUSIN` and `EVENT_CLICK_DATA_API`
     * Do not move `document` in `htmlElements` array
     * It will remove `EVENT_CLICK_DATA_API` event that should remain
     */
    EventHandler.off(document, EVENT_FOCUSIN)
  }",
      "after": "  dispose() {
    [window, this._dialog]
      .forEach(htmlElement => EventHandler.off(htmlElement, EVENT_KEY))

    this._backdrop.dispose()
    super.dispose()

    /**
     * `document` has 2 events `EVENT_FOCUSIN` and `EVENT_CLICK_DATA_API`
     * Do not move `document` in `htmlElements` array
     * It will remove `EVENT_CLICK_DATA_API` event that should remain
     */
    EventHandler.off(document, EVENT_FOCUSIN)
    if (this._focusTrapHandler) {
      this._element.removeEventListener('keydown', this._focusTrapHandler)
    }
  }"
    }
  ],
  "expected_accessibility_effect": "Shift+Tab from the first focusable element in the modal (close button) will wrap focus to the last focusable element (Delete button), and Tab from the last focusable element will wrap to the first, satisfying WCAG 2.1.1 (Keyboard) and 2.4.3 (Focus Order) for modal dialogs.",
  "functional_risks": [
    "The focus trap handler may conflict with nested modals or other focus management scripts if multiple modals are open.",
    "The focusable selector may not capture all focusable elements (e.g., custom elements with tabindex="0")."
  ],
  "verification_requirements": [
    "Run the frozen journey: Shift+Tab from #confirm-close must land on #confirm-delete.",
    "Tab from #confirm-delete must land on #confirm-close.",
    "Focus must not escape the modal when Tab/Shift+Tab are pressed.",
    "Existing keyboard dismissal (Escape) and backdrop click behavior must remain unchanged."
  ]
}
